SELECT COUNT(1)
FROM reservation
WHERE reservation_date = #{reservationDate}
AND reservation_phone = #{reservationPhone}
AND reservation_status = 0


SELECT COUNT(1) > 0
FROM reservation
WHERE table_id = #{tableId}
  AND reservation_date = #{reservationDate}
  AND reservation_time = #{reservationTime}
  AND reservation_status = 0  -- 未報到或有效預約

